from decimal import Decimal
from src.services.payments import (
    Payment, refund_payment, PaymentNotFoundError, PaymentNotRefundableError,
)

class MemRepo:
    def __init__(self, payments): self.payments = payments; self.saved = []
    def get(self, pid): return self.payments.get(pid)
    def save_refund(self, pid, amount): self.saved.append((pid, amount)); self.payments[pid] = Payment(pid, self.payments[pid].amount, amount, self.payments[pid].status)

class OkGateway:
    def process_refund(self, pid, amount): pass

class FailGateway:
    def process_refund(self, pid, amount): raise RuntimeError("down")

class UoW:
    def __init__(self): self.committed = False
    def begin(self): return self
    def __enter__(self): return None
    def __exit__(self, *a): pass
    def commit(self): self.committed = True
    def rollback(self): pass

class Notifier:
    def __init__(self): self.called = []
    def notify_refunded(self, p, a): self.called.append((p.id, a))

repo = MemRepo({"p1": Payment("p1", Decimal("10.00"), Decimal("0"), "settled")})
uow = UoW(); notif = Notifier()
result = refund_payment("p1", Decimal("4.00"), repo, OkGateway(), uow, notif)
assert result.refunded_amount == Decimal("4.00") and uow.committed and notif.called == [("p1", Decimal("4.00"))]
assert refund_payment("p1", Decimal("6.00"), repo, OkGateway(), UoW(), None).refunded_amount == Decimal("10.00")

for exc, args in [
    (PaymentNotFoundError, ("pX", Decimal("1.00"), MemRepo({}), OkGateway(), UoW(), None)),
    (PaymentNotRefundableError, ("p1", Decimal("0"), MemRepo({"p1": Payment("p1", Decimal("10"), Decimal("0"), "settled")}), OkGateway(), UoW(), None)),
    (PaymentNotRefundableError, ("p1", Decimal("1.00"), MemRepo({"p1": Payment("p1", Decimal("10"), Decimal("0"), "pending")}), OkGateway(), UoW(), None)),
    (PaymentNotRefundableError, ("p1", Decimal("11.00"), MemRepo({"p1": Payment("p1", Decimal("10"), Decimal("0"), "settled")}), OkGateway(), UoW(), None)),
]:
    try: refund_payment(*args); assert False
    except exc: pass

try:
    refund_payment("p1", Decimal("1.00"), MemRepo({"p1": Payment("p1", Decimal("10"), Decimal("0"), "settled")}), FailGateway(), UoW(), notif); assert False
except Exception as e:
    assert type(e).__name__ == "RefundFailedError"

print("all service-layer behavior checks passed")
